import { test, expect } from '@playwright/test';

test.describe('User Timezone Settings', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login if required
    const loginButton = page.getByRole('button', { name: /sign in|login/i });
    if (await loginButton.isVisible()) {
      await loginButton.click();
      await page.getByLabel(/email|username/i).fill('testuser@example.com');
      await page.getByLabel(/password/i).fill('TestPassword123!');
      await page.getByRole('button', { name: /sign in|login/i }).click();
      await page.waitForURL(/dashboard|home/);
    }

    // Navigate to profile settings
    const profileMenu = page.getByRole('button', { name: /profile|account|settings/i });
    await profileMenu.click();
    const settingsLink = page.getByRole('menuitem', { name: /settings|preferences/i });
    await settingsLink.click();
    await page.waitForURL(/settings|preferences/);
  });

  test('should display timezone settings section', async ({ page }) => {
    // Verify timezone settings section is visible
    const timezoneSection = page.getByRole('heading', { name: /timezone|time zone/i });
    await expect(timezoneSection).toBeVisible();

    // Verify timezone dropdown/select is present
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);
    await expect(timezoneSelect).toBeVisible();
  });

  test('should successfully change timezone to a different value', async ({ page }) => {
    // Get the timezone select element
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);

    // Click to open the dropdown
    await timezoneSelect.click();

    // Select a specific timezone (e.g., America/New_York)
    const timezoneOption = page.getByRole('option', { name: /america\/new_york|eastern|est|edt/i });
    await timezoneOption.click();

    // Verify the selection was made
    await expect(timezoneSelect).toHaveValue(/america\/new_york|eastern/i);

    // Look for and click save button
    const saveButton = page.getByRole('button', { name: /save|apply|update/i });
    await saveButton.click();

    // Wait for success message
    const successMessage = page.getByText(/timezone.*updated|settings.*saved|changes.*saved/i);
    await expect(successMessage).toBeVisible();
  });

  test('should persist timezone selection after page reload', async ({ page }) => {
    // Get the timezone select element
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);

    // Click to open the dropdown
    await timezoneSelect.click();

    // Select a specific timezone
    const timezoneOption = page.getByRole('option', { name: /europe\/london|gmt|bst/i });
    await timezoneOption.click();

    // Save the changes
    const saveButton = page.getByRole('button', { name: /save|apply|update/i });
    await saveButton.click();

    // Wait for success message
    const successMessage = page.getByText(/timezone.*updated|settings.*saved|changes.*saved/i);
    await expect(successMessage).toBeVisible();

    // Reload the page
    await page.reload();

    // Verify the timezone selection persists
    const reloadedTimezoneSelect = page.getByLabel(/timezone|time zone/i);
    await expect(reloadedTimezoneSelect).toHaveValue(/europe\/london|gmt/i);
  });

  test('should display all available timezones in dropdown', async ({ page }) => {
    // Get the timezone select element
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);

    // Click to open the dropdown
    await timezoneSelect.click();

    // Verify multiple timezone options are available
    const timezoneOptions = page.getByRole('option');
    const optionCount = await timezoneOptions.count();

    // Should have at least 10 timezone options
    expect(optionCount).toBeGreaterThanOrEqual(10);

    // Verify some common timezones are present
    const utcOption = page.getByRole('option', { name: /utc|gmt/i });
    await expect(utcOption).toBeVisible();

    const usOption = page.getByRole('option', { name: /america\/los_angeles|pst|pdt/i });
    await expect(usOption).toBeVisible();
  });

  test('should show validation error for invalid timezone selection', async ({ page }) => {
    // Get the timezone select element
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);

    // Try to set an invalid value directly if possible
    await timezoneSelect.fill('invalid/timezone');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save|apply|update/i });
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid|error|not.*valid|please.*select/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should allow timezone change from UTC to Asia/Tokyo', async ({ page }) => {
    // Get the timezone select element
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);

    // Verify current timezone (should be UTC or default)
    const currentValue = await timezoneSelect.inputValue();
    expect(currentValue).toBeTruthy();

    // Click to open the dropdown
    await timezoneSelect.click();

    // Select Asia/Tokyo timezone
    const tokyoOption = page.getByRole('option', { name: /asia\/tokyo|jst|japan/i });
    await tokyoOption.click();

    // Verify the selection
    await expect(timezoneSelect).toHaveValue(/asia\/tokyo|jst/i);

    // Save the changes
    const saveButton = page.getByRole('button', { name: /save|apply|update/i });
    await saveButton.click();

    // Verify success
    const successMessage = page.getByText(/timezone.*updated|settings.*saved|changes.*saved/i);
    await expect(successMessage).toBeVisible();
  });

  test('should display current timezone as selected in dropdown', async ({ page }) => {
    // Get the timezone select element
    const timezoneSelect = page.getByLabel(/timezone|time zone/i);

    // Get the current selected value
    const selectedValue = await timezoneSelect.inputValue();

    // Verify a value is selected
    expect(selectedValue).toBeTruthy();
    expect(selectedValue.length).toBeGreaterThan(0);

    // Click to open dropdown
    await timezoneSelect.click();

    // Verify the selected option is highlighted or matches current value
    const selectedOption = page.getByRole('option', { selected: true });
    await expect(selectedOption).toBeVisible();
  });
});
